#!/usr/bin/env node
// Builds the classic-script bridge to src/core for legacy pages:
//   src/app/bootstrap/legacy-bridge.js → assets/core/atomurus-core.js (IIFE)
// Committed like the other generated assets; `--check` fails when the
// committed file is stale (used by test:architecture-boundaries).
import { build } from 'esbuild';
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(ROOT, 'assets/core/atomurus-core.js');
const BANNER = '/* Atomurus core bridge — GENERATED by tools/build-core-bundle.mjs from src/. Do not edit. */';

export async function bundleCore() {
  const result = await build({
    entryPoints: [path.join(ROOT, 'src/app/bootstrap/legacy-bridge.js')],
    bundle: true,
    format: 'iife',
    platform: 'browser',
    target: ['es2020', 'chrome90', 'safari14', 'firefox90'],
    minify: true,
    legalComments: 'none',
    write: false,
    banner: { js: BANNER },
    logLevel: 'silent'
  });
  return result.outputFiles[0].text;
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const text = await bundleCore();
  if (process.argv.includes('--check')) {
    const current = existsSync(OUT) ? readFileSync(OUT, 'utf8') : '';
    if (current !== text) {
      console.error('assets/core/atomurus-core.js is stale — run `npm run build:core`');
      process.exit(1);
    }
    console.log('core bundle up to date');
  } else {
    mkdirSync(path.dirname(OUT), { recursive: true });
    writeFileSync(OUT, text);
    console.log(`wrote assets/core/atomurus-core.js (${text.length} bytes)`);
  }
}
